    [240+Math.sin(t*0.25)*160,120+Math.cos(t*0.45)*100,0.04,3.0,2]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
