  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+mod*0.4+vein*0.15)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-t*0.3)*Math.cos(sy*0.18+t*0.4)*0.3)*1.5)*0.25;
  const pulse=Math.sin(t*0.5)*0.1;
